/*
 * A068229  Primes congruent to 7 (mod 12).
 * https://oeis.org/A068229
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   primes congruent to 7 (mod 12) – generated by scanning *
 *            candidates of the form 12k+7 and testing each for primality
 * Range:     u8 n <= 14, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
#include "../utils/is_prime.h"   /* provides: bool is_prime(idx_t) */

seq_t a(idx_t n)
{
    /* Return 0 for non‑positive indices (outside the sequence offset). */
    if (n < 1)
        return 0;

    /* Static cache of already computed terms */
    static seq_t *cache = NULL;   /* array of terms, 0‑based */
    static size_t cap    = 0;     /* currently allocated capacity   */
    static size_t len    = 0;     /* number of terms stored          */
    static idx_t next    = 7;     /* next candidate of the form 12k+7 */

    /* If the requested term is already cached, return it immediately. */
    if ((size_t)n <= len)
        return cache[n - 1];

    /* Grow the cache if necessary. */
    if (cap < (size_t)n) {
        size_t new_cap = cap ? cap << 1 : 16; /* double or start at 16 */
        while (new_cap < (size_t)n)
            new_cap <<= 1;
        seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) /* allocation failed – return 0 as a sentinel value */
            return 0;
        cache = tmp;
        cap   = new_cap;
    }

    /* Generate and cache terms until the requested index is reached. */
    while (len < (size_t)n) {
        if (is_prime(next)) {
            cache[len++] = (seq_t)next;
        }
        next += 12;  /* next candidate of the form 12k+7 */
    }

    return cache[n - 1];
}
